import { definePluginSettings } from "@api/Settings";
import definePlugin, { OptionType } from "@utils/types";
import { React } from "@webpack/common";

function BdPluginInfoComponent() {
    const status = instance ? "Running" : "Stopped";
    return (
        <div style={{ padding: "16px", backgroundColor: "var(--background-secondary)", borderRadius: "8px", marginBottom: "16px" }}>
            <h3 style={{ margin: "0 0 8px", fontSize: "16px" }}>CrossPlatformPlaying</h3>
            <p style={{ margin: "0 0 4px", color: "var(--text-muted)" }}>Status: {status}</p>
            <p style={{ margin: "0", color: "var(--text-muted)", fontSize: "13px" }}>BetterDiscord plugin running inside Vencord</p>
            <p style={{ margin: "4px 0 0", color: "var(--text-muted)", fontSize: "13px" }}>Author: Giorgio</p>
        </div>
    );
}

// â”€â”€ BD settings sync â”€â”€
function bdSettingsLoad(): Record<string, any> {
    try {
        const raw = localStorage.getItem("bd_CrossPlatformPlaying_settings");
        return raw ? JSON.parse(raw) : {};
    } catch { return {}; }
}
function bdSettingsSave(settings: Record<string, any>) {
    try { localStorage.setItem("bd_CrossPlatformPlaying_settings", JSON.stringify(settings)); } catch {}
}
// Read BD defaults from the instance if available, else from localStorage
function getBdDefault(key: string, fallback: any): any {
    const s = bdSettingsLoad();
    return s[key] !== undefined ? s[key] : fallback;
}
function bdSavePlatform(platform: string, key: string, value: any) {
    const lsKey = 'bd_CrossPlatformPlaying_' + platform;
    try {
        const data = JSON.parse(localStorage.getItem(lsKey) || '{}');
        data[key] = value;
        localStorage.setItem(lsKey, JSON.stringify(data));
    } catch {}
}

