const BD_SOURCE = atob("");

let instance: any = null;

function startBdPlugin() {
    if (instance) return;
    try {
        const mod = { exports: {} };
        const BdApi = createBdApi();
        try { (window as any).BdApi = BdApi; } catch {}
        const fn = new Function("module", "exports", "BdApi", "window", BD_SOURCE);
        fn(mod, mod.exports, BdApi, window);
        const cls = mod.exports;
        if (typeof cls !== "function") {
            console.warn("[bd_accountswitcher] No class exported");
            return;
        }
        instance = new cls({ name: "CrossPlatformPlaying", version: "1.0.0" });
        if (typeof instance.start === "function")
            instance.start();
        console.log("[bd_accountswitcher] Loaded");
    } catch (e) {
        console.error("[bd_accountswitcher] Error:", e);
    }
}

function stopBdPlugin() {
    if (instance && typeof instance.stop === "function") {
        try { instance.stop(); } catch {}
    }
    instance = null;
    try { (window as any).BdApi?.Patcher?.unpatchAll("bd_accountswitcher"); } catch {}
    const styles = document.querySelectorAll("style[id^='bd_accountswitcher']");
    styles.forEach(s => s.remove());
}

export default definePlugin({
    name: "CrossPlatformPlaying",
    description: "Show what friends are playing even if they have their game activity turned off (BD plugin)",
    authors: [{ name: "Giorgio" }],
    settings,
    start() { startBdPlugin(); },
    stop() { stopBdPlugin(); }
});